SELECT ast25_price_id
  FROM ast25_price
 WHERE ast25_company_id = #{companyId}
   AND ast25_std_date   = #{stdDate}
   AND ast25_item_type  = #{itemType}
   AND ast25_item_cd    = #{itemCode}
 LIMIT 1

mapper.update:
WITH upsert AS ( UPDATE ast25_price
                    SET ast25_std_date   = #{stdDate}
                      , ast25_item_type  = #{itemType}
                      , ast25_item_cd    = #{itemCode}
                      , ast25_item_nm    = #{itemName}
                      , ast25_eval_price = #{evalPrice}
                      , ast25_note       = #{note}
                  WHERE ast25_price_id = #{priceId}
                 RETURNING * )
INSERT INTO ast25_price
SELECT #{priceId}, #{companyId}, #{stdDate}, #{itemType}, #{itemCode}, #{itemName}, #{evalPrice}, #{note}
 WHERE NOT EXISTS ( SELECT * FROM upsert )
